CREATE TABLE IF NOT EXISTS repositories (id TEXT PRIMARY KEY, name TEXT NOT NULL, path TEXT NOT NULL, primary_language TEXT NOT NULL DEFAULT '', file_count INTEGER NOT NULL DEFAULT 0, indexed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS repository_files (repository_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, path TEXT NOT NULL, language TEXT NOT NULL DEFAULT '', size BIGINT NOT NULL, hash TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', PRIMARY KEY (repository_id, path));
CREATE TABLE IF NOT EXISTS symbols (repository_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, file_path TEXT NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL, line INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS symbols_repository_name_idx ON symbols(repository_id, name);
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, repository_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL, error TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS tasks_repository_created_idx ON tasks(repository_id, created_at);
CREATE TABLE IF NOT EXISTS task_runs (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, status TEXT NOT NULL, started_at TIMESTAMPTZ NOT NULL, ended_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS task_steps (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, run_id TEXT NOT NULL REFERENCES task_runs(id) ON DELETE CASCADE, agent_name TEXT NOT NULL, step_type TEXT NOT NULL, status TEXT NOT NULL, input JSONB, output JSONB, error TEXT NOT NULL DEFAULT '', started_at TIMESTAMPTZ NOT NULL, ended_at TIMESTAMPTZ, latency_ms BIGINT NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS task_steps_task_started_idx ON task_steps(task_id, started_at);
CREATE TABLE IF NOT EXISTS tool_calls (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, run_id TEXT NOT NULL REFERENCES task_runs(id) ON DELETE CASCADE, step_id TEXT NOT NULL REFERENCES task_steps(id) ON DELETE CASCADE, tool_name TEXT NOT NULL, provider_type TEXT NOT NULL, request_payload JSONB, response_payload JSONB, status TEXT NOT NULL, error TEXT NOT NULL DEFAULT '', started_at TIMESTAMPTZ NOT NULL, ended_at TIMESTAMPTZ, latency_ms BIGINT NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS tool_calls_task_started_idx ON tool_calls(task_id, started_at);
CREATE TABLE IF NOT EXISTS artifacts (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, run_id TEXT NOT NULL REFERENCES task_runs(id) ON DELETE CASCADE, type TEXT NOT NULL, name TEXT NOT NULL, content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS memory_entries (id TEXT PRIMARY KEY, repository_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, task_id TEXT REFERENCES tasks(id) ON DELETE SET NULL, kind TEXT NOT NULL, content TEXT NOT NULL, source TEXT NOT NULL DEFAULT '', score DOUBLE PRECISION NOT NULL DEFAULT 0, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, embedding JSONB NOT NULL DEFAULT '[]'::jsonb, last_accessed_at TIMESTAMPTZ, access_count INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL);
ALTER TABLE memory_entries ADD COLUMN IF NOT EXISTS source TEXT NOT NULL DEFAULT '';
ALTER TABLE memory_entries ADD COLUMN IF NOT EXISTS score DOUBLE PRECISION NOT NULL DEFAULT 0;
ALTER TABLE memory_entries ADD COLUMN IF NOT EXISTS metadata JSONB NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE memory_entries ADD COLUMN IF NOT EXISTS embedding JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE memory_entries ADD COLUMN IF NOT EXISTS last_accessed_at TIMESTAMPTZ;
ALTER TABLE memory_entries ADD COLUMN IF NOT EXISTS access_count INTEGER NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS memory_repository_score_idx ON memory_entries(repository_id, score DESC, created_at DESC);
CREATE INDEX IF NOT EXISTS memory_repository_access_idx ON memory_entries(repository_id, last_accessed_at DESC, access_count DESC);
CREATE TABLE IF NOT EXISTS benchmark_cases (id TEXT PRIMARY KEY, name TEXT NOT NULL, repository_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL, expected JSONB NOT NULL DEFAULT '[]'::jsonb, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS benchmark_cases_repository_idx ON benchmark_cases(repository_id, created_at);
CREATE TABLE IF NOT EXISTS evaluation_runs (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES benchmark_cases(id) ON DELETE CASCADE, task_id TEXT REFERENCES tasks(id) ON DELETE SET NULL, mode TEXT NOT NULL, status TEXT NOT NULL, passed BOOLEAN NOT NULL DEFAULT FALSE, duration_ms BIGINT NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', started_at TIMESTAMPTZ NOT NULL, ended_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS evaluation_runs_case_idx ON evaluation_runs(case_id, created_at);
CREATE TABLE IF NOT EXISTS evaluation_batches (id TEXT PRIMARY KEY, name TEXT NOT NULL, mode TEXT NOT NULL, status TEXT NOT NULL, total INTEGER NOT NULL DEFAULT 0, completed INTEGER NOT NULL DEFAULT 0, passed INTEGER NOT NULL DEFAULT 0, started_at TIMESTAMPTZ NOT NULL, ended_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL);
ALTER TABLE evaluation_runs ADD COLUMN IF NOT EXISTS batch_id TEXT REFERENCES evaluation_batches(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS evaluation_runs_batch_idx ON evaluation_runs(batch_id, created_at);
